<script setup>
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import { reactive } from 'vue';
import AppSelect from '../../../Components/AppSelect.vue';
import PlatformLayout from '../../../Layouts/PlatformLayout.vue';
const props = defineProps({ listings: Array, claims: Array, reports: Array, filters: Object, statusOptions: Array, pagination: Object, claimProofMethods: Array });
const filter = useForm({ status: props.filters.status || '' });
const proofForms = reactive(Object.fromEntries(props.claims.map((claim) => [claim.id, {
    proof_method: props.claimProofMethods[0]?.value || '',
    proof_notes: '',
}])));
function applyFilter() { router.get('/platform/directory', { status: filter.status || undefined }, { preserveState: true, replace: true }); }
function claimAction(claim, action) { const review_notes = window.prompt(`Add a note explaining why you want to ${action} this request:`); if (!review_notes) return; router.post(`/platform/directory/claims/${claim.id}/${action}`, { review_notes }, { preserveScroll: true }); }
function verifyProof(claim) { router.post(`/platform/directory/claims/${claim.id}/verify-proof`, proofForms[claim.id], { preserveScroll: true }); }
function reportAction(report, status) { const review_notes = window.prompt(`Add a note before marking this feedback ${status}:`); if (!review_notes) return; router.patch(`/platform/directory/reports/${report.id}`, { status, review_notes }, { preserveScroll: true }); }
</script>

<template><Head title="Public venue guide" /><PlatformLayout><div class="space-y-9">
    <div class="flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between"><div><p class="eyebrow">Help players find more places</p><h1 class="mt-2 text-3xl font-semibold tracking-tight">Public venue guide</h1><p class="mt-3 max-w-3xl text-sm leading-6 text-slate-600">Add useful venue details before an owner joins FinACourt. Every page should come from a trustworthy public source and must never promise live booking.</p></div><Link href="/platform/directory/create" class="rounded-xl bg-court-700 px-5 py-3 text-sm font-semibold text-white">Add a venue</Link></div>

    <section v-if="claims.length" class="space-y-4"><div><p class="eyebrow">Ownership reviews</p><h2 class="mt-2 text-2xl font-semibold">Venues waiting for independent confirmation</h2><p class="mt-2 max-w-3xl text-sm leading-6 text-slate-600">Claimant-provided contact details and descriptions are not proof. Confirm control through an existing public venue contact or documented offline check before approval.</p></div><article v-for="claim in claims" :key="claim.id" class="app-card p-6"><div class="grid gap-5 lg:grid-cols-[1fr_auto]"><div><div class="flex flex-wrap gap-2"><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-semibold">{{ claim.proof_status_label }}</span><span v-if="claim.proof_method" class="rounded-full bg-court-50 px-3 py-1 text-xs font-semibold text-court-800">{{ claim.proof_method }}</span></div><h3 class="mt-3 text-lg font-semibold">{{ claim.listing.name }}</h3><p class="mt-1 text-sm text-slate-500">{{ claim.listing.city }}, {{ claim.listing.province }} · Requested for {{ claim.organization.name }}</p><dl class="mt-4 grid gap-3 text-sm sm:grid-cols-2"><div><dt class="text-slate-400">Requester</dt><dd class="font-medium">{{ claim.requester.name }} · {{ claim.requester.email }}</dd></div><div><dt class="text-slate-400">Claimant-supplied contact</dt><dd class="font-medium">{{ claim.relationship }} · {{ claim.verification_contact }}</dd></div></dl><p class="mt-4 whitespace-pre-line rounded-xl bg-slate-50 p-4 text-sm leading-6 text-slate-700">{{ claim.evidence_details }}</p><div v-if="claim.proof_status !== 'verified'" class="mt-4 rounded-xl border border-amber-200 bg-amber-50 p-4"><p class="text-sm font-semibold text-amber-950">Record only an independent check</p><p class="mt-1 text-xs leading-5 text-amber-800">Use contact details from the existing public source—not details supplied by the claimant. Do not paste identity documents or sensitive numbers into these notes.</p><div class="mt-3 grid gap-3 sm:grid-cols-2"><AppSelect v-model="proofForms[claim.id].proof_method" :options="claimProofMethods" placeholder="Verification method" /><textarea v-model="proofForms[claim.id].proof_notes" rows="3" minlength="20" maxlength="3000" class="rounded-xl border border-amber-200 bg-white px-3 py-2 text-sm" placeholder="What source did you independently check, and what confirmed venue control?"></textarea></div><button class="mt-3 rounded-xl bg-amber-900 px-4 py-2.5 text-sm font-semibold text-white" @click="verifyProof(claim)">Record independent proof</button></div><div v-else class="mt-4 rounded-xl border border-court-200 bg-court-50 p-4 text-sm text-court-900"><strong>Proof confirmed.</strong><span v-if="claim.can_approve"> The safety hold has finished; review disputes before approval.</span><span v-else> Approval remains locked until {{ claim.approval_available_at }}.</span></div></div><div class="flex gap-2 lg:flex-col"><button v-if="claim.can_approve" class="rounded-xl bg-court-700 px-4 py-2.5 text-sm font-semibold text-white" @click="claimAction(claim, 'approve')">Approve private access</button><span v-else class="rounded-xl bg-slate-100 px-4 py-2.5 text-center text-xs font-semibold text-slate-500">Approval locked</span><button class="rounded-xl border border-red-200 px-4 py-2.5 text-sm font-semibold text-red-700" @click="claimAction(claim, 'reject')">Reject request</button></div></div></article></section>

    <section v-if="reports.length" class="space-y-4"><div><p class="eyebrow">Keep details accurate</p><h2 class="mt-2 text-2xl font-semibold">Suggested corrections</h2></div><article v-for="report in reports" :key="report.id" class="app-card p-5"><div class="flex flex-col gap-4 sm:flex-row sm:justify-between"><div><h3 class="font-semibold">{{ report.listing.name }} · {{ report.report_type }}</h3><p class="mt-2 whitespace-pre-line text-sm text-slate-600">{{ report.details }}</p><p v-if="report.contact_email" class="mt-2 text-xs text-slate-400">Contact: {{ report.contact_email }}</p></div><div class="flex gap-2"><button class="rounded-xl bg-court-700 px-4 py-2 text-sm font-semibold text-white" @click="reportAction(report, 'resolved')">Mark updated</button><button class="rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold" @click="reportAction(report, 'dismissed')">No change needed</button></div></div></article></section>

    <section><div class="mb-4 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="eyebrow">All venues</p><h2 class="mt-2 text-2xl font-semibold">Venue guide</h2></div><form class="flex items-end gap-2" @submit.prevent="applyFilter"><label class="text-xs font-semibold uppercase tracking-wider text-slate-500">Show<AppSelect v-model="filter.status" :options="[{ value: '', label: 'Every status' }, ...statusOptions]" size="sm" class="mt-1 min-w-56 normal-case tracking-normal" /></label><button class="rounded-xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold">Apply</button></form></div><div class="grid gap-4 md:grid-cols-2"><article v-for="listing in listings" :key="listing.slug" class="app-card p-5"><div class="flex items-start justify-between gap-4"><div><span class="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-semibold">{{ listing.status_label }}</span><h3 class="mt-3 text-lg font-semibold">{{ listing.name }}</h3><p class="mt-1 text-sm text-slate-500">{{ listing.city }}, {{ listing.province }}</p></div><Link :href="`/platform/directory/${listing.slug}/edit`" class="rounded-xl border border-slate-200 px-3 py-2 text-sm font-semibold">Open</Link></div><div class="mt-4 flex flex-wrap gap-2"><span v-for="sport in listing.sports" :key="sport" class="rounded-full bg-court-50 px-2.5 py-1 text-xs text-court-800">{{ sport }}</span></div><dl class="mt-4 grid grid-cols-2 gap-3 text-xs text-slate-500"><div><dt class="text-slate-400">Information source</dt><dd class="mt-1">{{ listing.source_type }}</dd></div><div><dt class="text-slate-400">Last checked</dt><dd class="mt-1">{{ listing.last_verified_at || 'Not checked yet' }}</dd></div></dl></article><div v-if="!listings.length" class="app-card p-12 text-center md:col-span-2"><h3 class="font-semibold">No venues here yet</h3><p class="mt-2 text-sm text-slate-500">Add venues only when their basic details come from a trustworthy public or licensed source.</p></div></div></section>
    <nav v-if="pagination.last_page > 1" class="flex justify-between text-sm"><a :href="pagination.previous || undefined" class="rounded-xl border border-slate-200 px-4 py-2">Previous</a><span class="text-slate-500">Page {{ pagination.current_page }} of {{ pagination.last_page }}</span><a :href="pagination.next || undefined" class="rounded-xl border border-slate-200 px-4 py-2">Next</a></nav>
</div></PlatformLayout></template>
